const firebaseConfig={apiKey:"AIzaSyA3BL6qvC6OkcLql_CBBTOCWXSuTuUuunU",authDomain:"gp-blog-admin.firebaseapp.com",projectId:"gp-blog-admin",storageBucket:"gp-blog-admin.firebasestorage.app",messagingSenderId:"454725222443",appId:"1:454725222443:web:e27f38252a4013824e2a6e",measurementId:"G-YB94M7KK2T"};firebase.apps&&firebase.apps.length||firebase.initializeApp(firebaseConfig);const blogDb=firebase.firestore();let _publishedPostsCache=null;async function fetchPublishedPosts(){if(_publishedPostsCache)return _publishedPostsCache;const e=await blogDb.collection("blogPosts").where("published","==",!0).get(),a=[];return e.forEach(e=>a.push({id:e.id,...e.data()})),a.sort((e,a)=>(a.createdAt?a.createdAt.toMillis():0)-(e.createdAt?e.createdAt.toMillis():0)),_publishedPostsCache=a,a}async function fetchPostBySlug(e){return(await fetchPublishedPosts()).find(a=>a.slug===e)||null}let _dailyCache=null;async function fetchPublishedDailyUpdates(e){if(!_dailyCache){const e=await blogDb.collection("dailyUpdates").where("published","==",!0).get(),a=[];e.forEach(e=>a.push({id:e.id,...e.data()})),a.sort((e,a)=>(a.createdAt?a.createdAt.toMillis():0)-(e.createdAt?e.createdAt.toMillis():0)),_dailyCache=a}return"number"==typeof e?_dailyCache.slice(0,e):_dailyCache}function blogFormatDate(e){return e?e.toDate().toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}):""}function blogReadTime(e){const a=(e.content||"").replace(/<[^>]*>/g," "),t=a.trim().length?a.trim().split(/\s+/).filter(Boolean).length:0;return Math.max(1,Math.round(t/200))}function blogCoverImage(e){return e.imageUrl||e.imageUrls&&e.imageUrls[0]||"assets/gp_logo.png"}function blogEscapeHtml(e){const a=document.createElement("div");return a.textContent=null==e?"":String(e),a.innerHTML}const BLOG_PUBLISHER_LOGO="assets/publisher-mark.webp",BLOG_PUBLISHER_NAME="Glyphic Palette";function blogCardHTML(e){const a=blogCoverImage(e),t=e.tags&&e.tags[0]||"Journal";return`\n    <a class="blog-card" href="blog-post.html?slug=${encodeURIComponent(e.slug)}">\n      <div class="blog-card-img">\n        <div class="blog-card-img-bg" style="background-image:url('${a}')" aria-hidden="true"></div>\n        <img src="${a}" alt="" loading="lazy">\n      </div>\n      <div class="blog-card-body">\n        <div class="blog-card-tagrow">\n          <span class="blog-card-tag">${blogEscapeHtml(t)}</span>\n          ${e.featured?'<span class="blog-card-featured">Featured</span>':""}\n        </div>\n        <h3 class="blog-card-title">${blogEscapeHtml(e.title)}</h3>\n        <p class="blog-card-excerpt">${blogEscapeHtml(e.excerpt||"")}</p>\n        <div class="blog-card-meta">\n          <span class="blog-card-publisher"><img class="blog-card-publisher-logo" src="${BLOG_PUBLISHER_LOGO}" alt="" loading="lazy">Glyphic Palette</span>\n          <span class="blog-card-dot">·</span>\n          <span>${blogFormatDate(e.createdAt)}</span>\n          <span class="blog-card-dot">·</span>\n          <span>${blogReadTime(e)} min read</span>\n        </div>\n      </div>\n    </a>`}